-- CONTROL-ALT-PROBES-4C (2026-10-26, pillar autonomy; agent_issues 1000214; follows migrations/2026-10-26-control-alternate-probes4.sql and -4b)
--
-- A second review of the 18 new probes, this time against the code that the controls describe, found one more clause that would turn red by itself. Clause 3 of the probe of
-- breach-doctor-own-issue-guard fails when an open BREACH-DOCTOR-1: issue older than 24 hours has no breach_diagnoses row ("not classified or counted"). The doctor classifies the issues that
-- have no doer only: qnfo-fleet-control bdLoadState marks an open issue owned when its description holds a code-task: line, when a live code task names it ("[issue #N]" goal) or when a live
-- work claim names it, and leaves it out of the cases. Read on live 2026-10-26 19:04Z: six open BREACH-DOCTOR-1: issues (1000427 to 1000431 and 1000433, filed by migration with a code-task line)
-- are 4.5 hours old with no case, which is correct, and they reach 24 hours at about 14:30Z tomorrow, when the drill would have filed CHAOS-DRILL-FAILED-1 control:breach-doctor-own-issue-guard
-- against a guard that is working. The one doctor issue without a code-task line (1000266) has 2 cases. The clause now reads an open doctor issue with no doer, by the doctor own rule: no
-- code-task line, no live code task, no live work claim. Clauses 1 and 2 are untouched. The new text was run read-only against live and reads ok.
-- The old probe text and window note are in bak_20261026_control_probes4c first. The Rollback line below does not read it: it replaces the new fragment by the old one and removes the note.
-- The UPDATEs are anchored on the text they replace or on a marker, so a second apply, or a probe someone has since changed, is left alone.
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261026_control_probes4c
-- Rollback: UPDATE control_alternate_probes SET probe_sql = replace(probe_sql, 'WHEN EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND instr(a.title, ''BREACH-DOCTOR-1:'') = 1 AND instr(COALESCE(a.description, ''''), ''code-task:'') = 0 AND a.created_at < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 86400) * 1000 AND NOT EXISTS (SELECT 1 FROM breach_diagnoses d WHERE d.issue_id = a.id) AND NOT EXISTS (SELECT 1 FROM work_claims w WHERE w.released_at IS NULL AND w.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') AND (w.issue_id = a.id OR w.path = ''issue:'' || a.id)) AND NOT EXISTS (SELECT 1 FROM code_tasks t WHERE t.status NOT IN (''failed'', ''closed'', ''superseded'', ''needs_human'') AND instr(COALESCE(t.goal, ''''), ''[issue #'' || a.id || '']'') > 0)) THEN ''an open doctor issue with no doer is older than 24 hours and has no breach_diagnoses row, so it is not classified or counted''', 'WHEN EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND instr(a.title, ''BREACH-DOCTOR-1:'') = 1 AND a.created_at < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 86400) * 1000 AND NOT EXISTS (SELECT 1 FROM breach_diagnoses d WHERE d.issue_id = a.id)) THEN ''an open doctor issue older than 24 hours has no breach_diagnoses row, so it is not classified or counted'''), window_note = replace(window_note, ' | CONTROL-ALT-PROBES-4C 2026-10-26: clause 3 reads only an open doctor issue with no doer (no code-task line, no live work claim, no live code task), because the doctor classifies the issues that have no doer and leaves an owned one alone: six owned doctor issues (1000427 to 1000433) have no case by design.', '') WHERE control = 'breach-doctor-own-issue-guard'
-- Rollback note: decision_log stays (append-only).

CREATE TABLE IF NOT EXISTS bak_20261026_control_probes4c AS
  SELECT control, probe_sql AS old_probe_sql, window_note AS old_window_note FROM control_alternate_probes WHERE control = 'breach-doctor-own-issue-guard';

UPDATE control_alternate_probes SET probe_sql = replace(probe_sql, 'WHEN EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND instr(a.title, ''BREACH-DOCTOR-1:'') = 1 AND a.created_at < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 86400) * 1000 AND NOT EXISTS (SELECT 1 FROM breach_diagnoses d WHERE d.issue_id = a.id)) THEN ''an open doctor issue older than 24 hours has no breach_diagnoses row, so it is not classified or counted''', 'WHEN EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND instr(a.title, ''BREACH-DOCTOR-1:'') = 1 AND instr(COALESCE(a.description, ''''), ''code-task:'') = 0 AND a.created_at < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 86400) * 1000 AND NOT EXISTS (SELECT 1 FROM breach_diagnoses d WHERE d.issue_id = a.id) AND NOT EXISTS (SELECT 1 FROM work_claims w WHERE w.released_at IS NULL AND w.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') AND (w.issue_id = a.id OR w.path = ''issue:'' || a.id)) AND NOT EXISTS (SELECT 1 FROM code_tasks t WHERE t.status NOT IN (''failed'', ''closed'', ''superseded'', ''needs_human'') AND instr(COALESCE(t.goal, ''''), ''[issue #'' || a.id || '']'') > 0)) THEN ''an open doctor issue with no doer is older than 24 hours and has no breach_diagnoses row, so it is not classified or counted''')
WHERE control = 'breach-doctor-own-issue-guard' AND instr(probe_sql, 'WHEN EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND instr(a.title, ''BREACH-DOCTOR-1:'') = 1 AND a.created_at < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 86400) * 1000 AND NOT EXISTS (SELECT 1 FROM breach_diagnoses d WHERE d.issue_id = a.id)) THEN ''an open doctor issue older than 24 hours has no breach_diagnoses row, so it is not classified or counted''') > 0;

UPDATE control_alternate_probes SET window_note = window_note || ' | CONTROL-ALT-PROBES-4C 2026-10-26: clause 3 reads only an open doctor issue with no doer (no code-task line, no live work claim, no live code task), because the doctor classifies the issues that have no doer and leaves an owned one alone: six owned doctor issues (1000427 to 1000433) have no case by design.'
WHERE control = 'breach-doctor-own-issue-guard' AND instr(window_note, 'CONTROL-ALT-PROBES-4C') = 0;

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'rem-a3-drills',
  'a probe that reads what a loop does to a record must read the loop own selection rule and not a simpler one, so the exemption it applies is the loop exemption: an issue with a doer is left alone by the doctor, and a probe that demands a case for it fails on a healthy guard',
  'CONTROL-ALT-PROBES-4C: clause 3 of the probe of breach-doctor-own-issue-guard reads an open doctor issue with no doer (no code-task line, no live work claim, no live code task) and no longer an owned one',
  'live qnfo-audit 2026-10-26 19:04Z: 7 open BREACH-DOCTOR-1: issues, 6 with a code-task line and no case (4.5 hours old, 24 hours at about 14:30Z tomorrow) and 1000266 with 2 cases; qnfo-fleet-control/worker.js bdLoadState owned = code-task line, live code task, live work claim, and the doctor classifies the rest; the new probe text reads ok on live. The offline suite migrations/control-alternate-probes4c.test.mjs replays the stored probe after the first file: an owned 25-hour-old doctor issue with no case FAILS before and reads ok after, an unowned one still FAILS, a live work claim or a live code task exempts it, a released claim or a failed task does not',
  'migration merged, the next 6-hourly drill reads the probe',
  'one stored probe text and one window note in control_alternate_probes, one backup table, read by the drill only',
  'the Rollback header replaces the new fragment by the old one and removes the note (decision_log stays: append-only)',
  'the guard probe stays green while owned doctor issues age past 24 hours, and still fails for an unowned doctor issue that was never classified',
  'no CHAOS-DRILL-FAILED-1 control:breach-doctor-own-issue-guard issue is filed for the six owned doctor issues when they pass 24 hours, and one is still filed for an unowned doctor issue with no case',
  'none',
  'd1:qnfo-audit agent_issues, breach_diagnoses, work_claims, code_tasks, control_alternate_probes (SELECT only), qnfo-fleet-control/worker.js bdLoadState, offline node:sqlite suite'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE instr(action, 'CONTROL-ALT-PROBES-4C:') = 1);
